<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DSWD MIMAROPA Kiosk</title><style>body{margin:0;font-family:Arial;background:#f3f6fb;color:#111827;height:100vh;overflow:hidden}.wrap{height:100vh;padding:12px;display:flex}.card{background:#fff;border-radius:18px;padding:14px;box-shadow:0 12px 35px #0002;width:100%;display:flex;flex-direction:column;gap:8px}h1{text-align:center;color:#00008b;margin:0;font-size:24px;letter-spacing:.5px}.note{text-align:center;color:#64748b;margin:0;font-size:12px}.forms{display:grid;grid-template-columns:1fr 1fr;gap:12px}.sec{background:#f8fafc;border:1px solid #d6dce8;border-radius:15px;padding:10px}.sec h2{margin:0 0 8px;color:#0f2f56;font-size:15px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.f{display:flex;flex-direction:column}.f label{font-size:11px;font-weight:900;margin-bottom:4px}.f input,.f select{height:36px;border:1px solid #cbd5e1;border-radius:10px;padding:0 9px;font-size:13px;background:white}.f select:disabled{background:#e5e7eb}.two{grid-column:span 2}.tiles{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;flex:1;min-height:0}.assist{border:0;border-radius:10px;background:#003f9e;color:white;box-shadow:0 5px 0 #002964,0 12px 22px #0003;font-weight:1000;font-size:18px;letter-spacing:2px;text-align:center;cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;text-transform:uppercase;line-height:1.05;min-height:105px}.assist .ico{font-size:31px;line-height:1}.assist:hover{filter:brightness(1.08);transform:translateY(-2px)}.assist:disabled{opacity:.55;cursor:not-allowed;transform:none}.cash{grid-column:2 / span 2}.status{text-align:center;font-weight:900;min-height:20px;color:#0f766e;font-size:12px}.err{color:#dc2626}.modal{position:fixed;inset:0;background:#0008;display:none;align-items:center;justify-content:center;padding:20px;z-index:10}.pop{background:white;border-radius:24px;padding:26px;max-width:520px;width:96%;text-align:center;box-shadow:0 24px 80px #0008}.pop h2{margin:0;color:#166534}.queue{font-size:68px;font-weight:1000;color:#00008b;margin:8px 0}.btn{border:0;border-radius:999px;padding:13px 22px;font-weight:900;cursor:pointer;margin:5px}.print{background:#16a34a;color:white}.again{background:#0b2e83;color:white}.stubwrap{display:none}.stub{width:80mm;max-width:80mm;margin:0 auto;padding:8mm 6mm;background:#fff}.stub h2{text-align:center;margin:0 0 6px}.row{display:flex;justify-content:space-between;border-bottom:1px dotted #aaa;font-size:12px;padding:5px 0;gap:10px}.row b{text-align:right}@media(max-width:950px){body{overflow:auto;height:auto}.wrap{height:auto}.forms{grid-template-columns:1fr}.tiles{grid-template-columns:1fr 1fr}.cash{grid-column:auto}.assist{min-height:95px}}@media(max-width:620px){.grid,.tiles{grid-template-columns:1fr}.assist{font-size:17px}.assist .ico{font-size:30px}}@media print{.wrap,.modal{display:none!important}.stubwrap{display:block}@page{size:80mm auto;margin:0}}</style></head><body><div class="wrap"><div class="card"><h1>DSWD MIMAROPA REGISTRATION KIOSK</h1><p class="note">Fill in beneficiary details, then tap the assistance type.</p><div class="forms"><div class="sec"><h2>Beneficiary Information</h2><div class="grid"><div class="f"><label>First Name *</label><input id="firstName"></div><div class="f"><label>Middle Name</label><input id="middleName"></div><div class="f"><label>Last Name *</label><input id="lastName"></div><div class="f"><label>Ext. Name</label><input id="extName"></div><div class="f two"><label>Contact Number *</label><input id="contactNumber" placeholder="09XXXXXXXXX" maxlength="13"></div></div></div><div class="sec"><h2>Complete Address</h2><div class="grid"><div class="f"><label>Province *</label><select id="province" onchange="loadCities()"><option value="">Loading...</option></select></div><div class="f"><label>City / Municipality *</label><select id="city" onchange="loadBarangays()" disabled><option value="">Select city</option></select></div><div class="f"><label>Barangay *</label><select id="barangay" disabled><option value="">Select barangay</option></select></div><div class="f"><label>House No. / Street / Sitio *</label><input id="street"></div></div></div></div><div id="status" class="status"></div><div class="tiles"><button class="assist" onclick="generateQueue('Medical Assistance')"><span class="ico">✚</span>Medical<br>Assistance</button><button class="assist" onclick="generateQueue('Funeral Assistance')"><span class="ico">▰</span>Funeral<br>Assistance</button><button class="assist" onclick="generateQueue('Educational Assistance')"><span class="ico">▱</span>Educational<br>Assistance</button><button class="assist" onclick="generateQueue('Transportation Assistance')"><span class="ico">▣</span>Transportation<br>Assistance</button><button class="assist" onclick="generateQueue('Material Assistance')"><span class="ico">□</span>Material<br>Assistance</button><button class="assist" onclick="generateQueue('Food Assistance')"><span class="ico">◫</span>Food<br>Assistance</button><button class="assist cash" onclick="generateQueue('Cash Relief Assistance')"><span class="ico">₱</span>Cash Relief<br>Assistance</button></div></div></div><div id="modal" class="modal"><div class="pop"><h2>Queue Generated</h2><div id="queueNo" class="queue">-</div><p id="summary"></p><button class="btn print" onclick="printStub()">Print Stub</button><button class="btn again" onclick="resetScreen()">New Queue</button></div></div><div class="stubwrap"><div class="stub"><h2>DSWD QUEUE STUB</h2><div class="row"><span>Queue Number</span><b id="stubQueue">-</b></div><div class="row"><span>Code</span><b id="stubCode">-</b></div><div class="row"><span>Name</span><b id="stubName">-</b></div><div class="row"><span>Contact</span><b id="stubContact">-</b></div><div class="row"><span>Assistance</span><b id="stubProgram">-</b></div><div class="row"><span>Address</span><b id="stubAddress">-</b></div><div class="row"><span>Date</span><b id="stubDate">-</b></div></div></div><script>const RC='170000000';let pc='',cc='',lastQueue=null;const province=document.getElementById('province'),city=document.getElementById('city'),barangay=document.getElementById('barangay');function msg(x,b=false){status.className='status'+(b?' err':'');status.textContent=x}async function api(p){let r=await fetch('../api/psgc.php?'+new URLSearchParams(p),{cache:'no-store'}),d=await r.json();if(!d.success)throw Error(d.message||'Address list unavailable');return d.items||[]}function fill(s,a,t){s.innerHTML='<option value="">'+t+'</option>';a.forEach(x=>{let o=new Option(x.name,x.name);o.dataset.code=x.code;s.add(o)});s.disabled=false}async function init(){try{msg('Loading address list...');let p=await api({type:'provinces',region_code:RC});p.push({name:'Independent City / No Province',code:'REGION_CITIES'});fill(province,p,'Select province/location');msg('Ready.')}catch(e){msg(e.message,true)}}async function loadCities(){pc=province.selectedOptions[0]?.dataset.code||'';cc='';city.innerHTML='<option value="">Select city</option>';barangay.innerHTML='<option value="">Select barangay</option>';city.disabled=true;barangay.disabled=true;if(!pc)return;try{msg('Loading cities...');let p=pc==='REGION_CITIES'?{type:'cities',region_code:RC}:{type:'cities',region_code:RC,province_code:pc};fill(city,await api(p),'Select city');msg('Ready.')}catch(e){msg(e.message,true)}}async function loadBarangays(){cc=city.selectedOptions[0]?.dataset.code||'';barangay.innerHTML='<option value="">Select barangay</option>';barangay.disabled=true;if(!cc)return;try{msg('Loading barangays...');fill(barangay,await api({type:'barangays',region_code:RC,province_code:pc==='REGION_CITIES'?'':pc,city_code:cc}),'Select barangay');msg('Ready.')}catch(e){msg(e.message,true)}}function v(id){return document.getElementById(id).value.trim()}function okPhone(x){return /^09\d{9}$/.test(x)||/^\+639\d{9}$/.test(x)||/^639\d{9}$/.test(x)}function validate(){if(!v('firstName')||!v('lastName'))return'Please enter first name and last name.';if(!okPhone(v('contactNumber')))return'Please enter a valid contact number.';if(!v('province')||!v('city')||!v('barangay')||!v('street'))return'Please complete all address dropdowns and street field.';return''}function lock(x){document.querySelectorAll('.assist').forEach(b=>b.disabled=x)}async function generateQueue(program){let e=validate();if(e){msg(e,true);return}msg('Checking duplicate records and generating queue...');lock(true);try{let body={first_name:v('firstName'),middle_name:v('middleName'),last_name:v('lastName'),ext_name:v('extName'),contact_number:v('contactNumber'),province:v('province'),city_municipality:v('city'),barangay:v('barangay'),street_address:v('street'),program_type:program};let r=await fetch('../api/kiosk_generate_queue.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!d.success)throw Error(d.message||'Unable to generate queue');lastQueue=d;queueNo.textContent=d.queue_number;summary.textContent=d.client_name+' - '+d.program_type+' - MIMAROPA';setStub(d);modal.style.display='flex';msg('Queue number ready.')}catch(x){msg(x.message,true)}finally{lock(false)}}function setStub(d){stubQueue.textContent=d.queue_number||'-';stubCode.textContent=d.beneficiary_code||'-';stubName.textContent=d.client_name||'-';stubContact.textContent=d.contact_number||'-';stubProgram.textContent=d.program_type||'-';stubAddress.textContent=d.address||'-';stubDate.textContent=d.date_time||new Date().toLocaleString()}function printStub(){if(lastQueue)setStub(lastQueue);setTimeout(()=>print(),80)}function resetScreen(){lastQueue=null;modal.style.display='none';msg('');['firstName','middleName','lastName','extName','contactNumber','street'].forEach(id=>document.getElementById(id).value='');province.value='';loadCities()}init();</script></body></html>